def main():
	rows = list(csv.DictReader(open(SRC, encoding="utf-8")))
	cols = list(rows[0].keys()) + ["slot", "art"]
	out = []
	for r in rows:
		r = dict(r)
		r["slot"] = SLOT_OF_EXISTING.get(r["tech_id"], "")
		r["art"] = ART_EXISTING.get(r["tech_id"], "")
		out.append(r)
	for n in NEW:
		d = {k: ("" if v is None else v) for k, v in n.items()}
		if not d["element"]:
			d["element"] = {"คม": "ฟัน", "ทุบ": "ทุบ", "แทง": "แทง", "ยิง": "แทง", "กล": "ทุบ", "มือเปล่า": "ทุบ"}[d["school"]]
		out.append(d)
	os.makedirs(os.path.dirname(OUT), exist_ok=True)
	with open(OUT, "w", encoding="utf-8", newline="") as f:
		w = csv.DictWriter(f, fieldnames=cols)
		w.writeheader()
		w.writerows(out)
	print(f"{OUT}: {len(out)} ท่า (เดิม {len(rows)} · ใหม่ {len(NEW)})")


if __name__ == "__main__":
	main()
